(* [comment removed for export] *)
Lemma AMBufOwn_aobj : forall LB LF es x sz, AMBufOwn LB es -> In (x, sz) es -> aobj LB LF x (mb_block_size sz).
Proof. intros LB LF es x sz OWN IN. destruct (OWN x sz IN) as [p INb]. eapply aobj_block; [exact INb| lia| lia]. Qed.

Lemma AMBufOwn_fsobj : forall s LB m0 LF es x sz, as_RHEAP H s LB m0 -> AMBufOwn LB es -> In (x, sz) es -> fsobj H LF x (mb_block_size sz).
Proof. intros s LB m0 LF es x sz RH OWN IN. destruct (OWN x sz IN) as [p INb]. eapply (fsobj_block H HH); [exact RH| exact INb]. Qed.

(* [comment removed for export] *)
Lemma AMBraw_ext : forall m m' b es out insz op oe,
  AMBraw m b es out insz op oe ->
  (forall A cs, rw_cells bsegs m A cs ->
     (b <= A /\ A + Z.of_nat (cells_size cs) <= b + 64)
     \/ (exists x sz, In (x, sz) es /\ x <= A /\ A + Z.of_nat (cells_size cs) <= x + mb_block_size sz) ->
     rw_cells bsegs m' A cs) ->
  (forall x sz, In (x, sz) es -> addressable m x (mb_block_size sz) -> addressable m' x (mb_block_size sz)) ->
  (accessible m b 64 -> accessible m' b 64) ->
  AMBraw m' b es out insz op oe.
Proof.
  intros m m' b es out insz op oe (ls & H0 & H1 & DL & LC & EL & AOK & SH & AB) KC KA KB.
  exists ls. split; [apply (KC _ _ H0); left; cbn; lia|]. split; [apply (KC _ _ H1); left; cbn; lia|].
  split; [exact DL|]. split.
  { intros a n La. destruct (LC a n La) as [WF C]. split; [exact WF|]. apply (KC _ _ C). rewrite LNodeCells_size.
    destruct (mb_lnode_cases _ _ _ _ _ DL AOK La) as [->|(sz & IN)]; [left; lia| right].
    destruct (mb_addr_ok_elem _ _ _ _ AOK IN) as (_ & _ & S0 & R1 & _). exists a, sz. split; [exact IN| lia]. }
  split.
  { intros x sz IN. destruct (EL x sz IN) as [junk C]. exists junk. apply (KC _ _ C). right. exists x, sz.
    destruct (mb_addr_ok_elem _ _ _ _ AOK IN) as (_ & _ & S0 & R1 & _).
    cbn [cells_size csize]. rewrite Nat.add_0_r, Nat2Z.inj_add, Z2Nat.id by lia. split; [exact IN| lia]. }
  split; [exact AOK|]. split; [intros x sz IN; exact (KA x sz IN (SH x sz IN))| exact (KB AB)].
Qed.

(* [comment removed for export] *)
Lemma AMBraw_apres : forall s LB m0 LF m1 SP m m' b es out insz op oe,
  as_RHEAP H s LB m0 -> as_RFS H LF m1 -> aobj LB LF b 64 -> AMBufOwn LB es ->
  AMBraw m b es out insz op oe -> apres H LB SP m m' -> AMBraw m' b es out insz op oe.
Proof.
  intros s LB m0 LF m1 SP m m' b es out insz op oe RH RF AOB OWN R AP.
  eapply AMBraw_ext; [exact R| | |].
  - intros A cs C [[K1 K2]|(x & sz & IN & K1 & K2)].
    + eapply (apres_rw_cells H); [exact AP| exact C|]. eapply (aobj_client H HH); [exact RH| exact RF| eapply aobj_sub; [exact AOB| exact K1| exact K2]].
    + destruct (OWN x sz IN) as [p INb]. eapply (apres_rw_cells H); [exact AP| exact C|]. eapply aclient_range_block; [exact INb| exact K1| exact K2].
  - intros x sz IN AD. destruct (OWN x sz IN) as [p INb]. eapply (apres_addressable H); [exact AP| exact AD| exact INb].
  - intros AC. eapply (aobj_apres_accessible H HH); [exact RH| exact RF| exact AOB| exact AP| exact AC| lia| lia].
Qed.
