(* [comment removed for export] *)
Lemma AMBraw_transport_scr : forall s LB m0 LF m1 X XS m m' b es out insz op oe,
  as_RHEAP H s LB m0 -> as_RFS H LF m1 -> aobj LB LF b 64 -> AMBufOwn LB es ->
  AMBraw m b es out insz op oe -> munch (X ++ XS) m m' -> wmono bsegs m m' -> Forall awin X -> Forall (fs_scratch H LF) XS ->
  disjoint_from X b 64 -> (forall x sz, In (x, sz) es -> disjoint_from X x (mb_block_size sz)) ->
