(* [comment removed for export] *)
Lemma prep_frame_acc : forall m ff d k (zs : list byte),
  0 <= ff -> ff mod 8 = 0 -> 0 <= d -> d mod 8 = 0 -> 0 <= k -> ff + d + 8 * k <= AAPP_HI ->
  rw_cells bsegs m (Z.shiftr ff 3 + 2147450880 + d / 8) [CB (Z.to_nat k) zs] -> zs = repeat (b8 0) (Z.to_nat k) ->
