(* [comment removed for export] *)
Lemma aobj_writes : forall s LB m0 LF m m' lo shi W,
  as_RHEAP H s LB m0 -> as_RFS H LF m -> ACONST m -> stack0 m lo shi -> munch W m m' -> wmono bsegs m m' ->
  Forall (fun iv : Z * Z => aceil <= fst iv \/ exists O n, aobj LB LF O n /\ O <= fst iv /\ fst iv <= snd iv /\ snd iv <= O + n) W ->
